      classes.root,
      {
        [classes.dense]: dense,
        [classes.padding]: !disablePadding,
        [classes.subheader]: subheader,
      },
      classNameProp,
    );

    return (
      <ComponentProp ref={rootRef} className={className} {...other}>
        {subheader}
        {children}
      </ComponentProp>
    );
  }
}

